static void ITEM_SaveSkillSelections(int * pnParam, D2UnitStrc * pUnit) {
    int32_t nSkillOwnerGUID;
    eD2Skills eSkillId;
    int nStatValue = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_hitpoints, 0);
    *pnParam = nStatValue;
    nStatValue = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_mana, 0);
    pnParam[1] = nStatValue;
    nStatValue = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_stamina, 0);
    pnParam[2] = nStatValue;
    D2SkillStrc* pSkill = D2Common::Units::GetLeftSkill(pUnit);
    if (pSkill) {
      nSkillOwnerGUID = D2Common::Skills::GetOwnerGUID(pSkill);
      pnParam[6] = nSkillOwnerGUID;
      eSkillId = D2Common::Skills::GetSkillId(pSkill, ".\\UNIT\\Item.cpp", 0x155);
      pnParam[4] = eSkillId;
    } else {
      pnParam[6] = -1;
      pnParam[4] = 0;
    }

    pSkill = D2Common::Units::GetRightSkill(pUnit);
    if (pSkill) {
      nSkillOwnerGUID = D2Common::Skills::GetOwnerGUID(pSkill);
      pnParam[5] = nSkillOwnerGUID;
      eSkillId = D2Common::Skills::GetSkillId(pSkill, ".\\UNIT\\Item.cpp", 0x161);
      pnParam[3] = eSkillId;
      return;
    }

    pnParam[5] = -1;
    pnParam[3] = 0;
}

// Restores a player's left- and right-skill selections from a saved skill state (pSkillSaveState). For each hand: if the saved skill is not SKILL_Attack and the skill exists and differs from the current selection, calls PLRSKILLS_CanUseSkillCheck and, if usable (not error codes 2 or 7), re-selects it via SelectSkillLeft/SelectSkillRight. Typically called after an item swap.
static void ITEM_RestoreSkillSelections(int * pSkillSaveState, D2UnitStrc * pUnit) {
    D2SkillStrc* pSkillLeft;
    D2SkillStrc* pCurrentSkill;
    int32_t nCanUseResult;
    if (pSkillSaveState[4] != SKILL_Attack) {
      pSkillLeft = D2Common::Skills::GetSkillByIdAndOwner(pUnit, pSkillSaveState[4], pSkillSaveState[6]);
      if (pSkillLeft) {
        pCurrentSkill = D2Common::Units::GetLeftSkill(pUnit);
        if (pSkillLeft != pCurrentSkill) {
          nCanUseResult = PlrSkills::PLRSKILLS_CanUseSkillCheck(pUnit, pSkillLeft);
          if (nCanUseResult != 2 && nCanUseResult != 7) {
            D2Common::Skills::SelectSkillLeft(pUnit, pSkillSaveState[4], pSkillSaveState[6]);
          }
        }
      }
    }
    if (pSkillSaveState[3] == SKILL_Attack) {
      return;
    }

    pSkillLeft = D2Common::Skills::GetSkillByIdAndOwner(pUnit, pSkillSaveState[3], pSkillSaveState[5]);
    if (!pSkillLeft) {
      return;
    }

    pCurrentSkill = D2Common::Units::GetRightSkill(pUnit);
    if (pSkillLeft == pCurrentSkill) {
      return;
    }

    nCanUseResult = PlrSkills::PLRSKILLS_CanUseSkillCheck(pUnit, pSkillLeft);
    if (!(nCanUseResult != 2 && nCanUseResult != 7)) {
      return;
    }

    D2Common::Skills::SelectSkillRight(pUnit, pSkillSaveState[3], pSkillSaveState[5]);
}

// @sourcefile .\UNIT\Item.cpp
static void __stdcall ITEM_RemoveItemFromBodyAndRecalc(int32_t nGfxComponent, D2UnitStrc * pUnit, D2UnitStrc * pUnit2) {
    if (!(pUnit2 && pUnit && pUnit2->pInventory)) {
      return;
    }

    D2Common::INVENTORY::Inventory::INVENTORY_SwapPrimaryWeaponOnRemoval(pUnit2->pInventory, pUnit);
    if (pUnit2->eUnitType == UNIT_PLAYER) {
      D2Common::INVENTORY::Inventory::GetEquipedWeapon(pUnit2->pInventory);
    }

    D2Common::ITEMS::Items::CheckItemFlag(pUnit, ITEMFLAG_BROKEN, 0x96, ".\\UNIT\\Item.cpp");
    D2Common::Stats::StatsEx::STATLIST_RemoveFromOwnerAndRecalc(pUnit2, pUnit);
    Engine::Gfx::GFX_ClearAllModeFlags(pUnit2, nGfxComponent);
}

static void __stdcall ITEM_ReequipItemOnBody(D2UnitStrc * pUnit, int32_t bApplyEquipStats, int32_t nGfxComponent, D2UnitStrc * pUnit2) {
    if (!(pUnit && pUnit2)) {
      return;
    }

    D2InventoryStrc* pInventory = pUnit->pInventory;
    if (!pInventory) {
      return;
    }

    eD2BodyLoc eBodyLoc = D2Common::ITEMS::Items::GetBodyLocation(pUnit2);
    if (!(eBodyLoc != BODYLOC_SWAPPED_R_ARM && eBodyLoc != BODYLOC_SWAPPED_L_ARM)) {
      return;
    }

    D2Common::INVENTORY::Inventory::INVENTORY_SwapPrimaryWeaponOnRemoval(pInventory, pUnit2);
    Engine::Gfx::GFX_ClearAllModeFlags(pUnit, nGfxComponent);
    if (bApplyEquipStats == 1) {
      D2UnitStrc* pStatOwner;
      pStatOwner = D2Common::Stats::StatsEx::SEVER_ITEM_GetOwner(pUnit2, nullptr);
      if (!pStatOwner) {
        ITEM_ApplySocketableAndEquipStats(1, pUnit, pUnit2);
      }
    }

    D2Common::INVENTORY::Inventory::INVENTORY_UpdatePrimaryWeapon(pInventory, pUnit2);
}

