// @sourcefile .\UNIT\Item.cpp
static void __stdcall ITEM_RemoveEquippedItemForSwap(D2UnitStrc * pItem, D2UnitStrc * pOwner) {
    BOOL bIsBroken;
    D2InventoryStrc* pInventory = pOwner->pInventory;
    eD2BodyLoc eBodyLoc = D2Common::ITEMS::Items::GetBodyLocation(pItem);
    uint32_t nBodyLocIdx = (uint32_t)eBodyLoc;
    if (nBodyLocIdx == 4 || nBodyLocIdx == 5) {
      uint8_t bVar1;
      D2Common::INVENTORY::Inventory::INVENTORY_SwapPrimaryWeaponOnRemoval(pInventory, pItem);
      bVar1 = D2Common::Units::GetItemComponent(pOwner, pItem);
      Engine::Gfx::GFX_ClearAllModeFlags(pOwner, (uint32_t)bVar1);
      D2Common::INVENTORY::Inventory::GetCurrentItemOnBodyLocation(pOwner, pInventory, &pItem, nBodyLocIdx);
    }

    D2UnitStrc* pOwnedItem = D2Common::INVENTORY::Inventory::ItemBelongsToInventoryOfPlayer(pInventory, pItem);
    if (pOwnedItem) {
      if (pOwner->eUnitType == UNIT_PLAYER) {
        D2Common::INVENTORY::Inventory::GetEquipedWeapon(pOwner->pInventory);
      }

      bIsBroken = D2Common::ITEMS::Items::CheckItemFlag(pOwnedItem, ITEMFLAG_BROKEN, 0x96, ".\\UNIT\\Item.cpp");
      if (!bIsBroken) {
        D2Common::Stats::StatsEx::STATLIST_RemoveFromOwnerAndRecalc(pOwner, pOwnedItem);
      }

      D2Common::INVENTORY::Inventory::NullSub_2Arg(pInventory, nBodyLocIdx);
    }
    if (!pItem) {
      CUnit::RemoveObjectFromServerObjectTable(-1, UNIT_COUNT);
      return;
    }

    CUnit::RemoveObjectFromServerObjectTable(pItem->nUnitGUID, pItem->eUnitType);
}

// Returns the drop-sound ID for an item unit. First reads wDropSound from the item's ItemsTxt row. If the item is unique (quality 7), overrides with the UniqueItemsTxt dropsound field; if set (quality 5), overrides with SetItemsTxt dropsound. Returns 0 for null input or when no positive sound is found.
int32_t __fastcall SOUND_GetIdFromUnit(D2UnitStrc * pUnit) {
    short int nDropSound;
    uint32_t nItemClassId;
    int32_t nSoundId = 0;
    if (!pUnit) {
      nItemClassId = -1;
    } else {
      nItemClassId = pUnit->nClassId;
    }

    D2ItemsTxt* pItemsTxt = D2Common::DATATBLS::ItemTbls::TXT_Items_GetLine(nItemClassId);
    if (pItemsTxt && pItemsTxt->wDropSound > 0) {
      nSoundId = (int32_t)pItemsTxt->wDropSound;
    }

    int eQuality = D2Common::ITEMS::Items::GetItemQuality(pUnit);
    if (eQuality == 7) {
      eQuality = D2Common::ITEMS::Items::ITEM_GetItemData_nFileIndex(pUnit);
      if (eQuality < 0) {
        return nSoundId;
      }

      eQuality = D2Common::ITEMS::Items::ITEM_GetItemData_nFileIndex(pUnit);
      if (eQuality < 0) {
        return nSoundId;
      }
      if (eQuality >= sgptDataTable->nTxtUniqueItemsSize) {
        return nSoundId;
      }
      if (!(sgptDataTable->pTxtUniqueItems + eQuality)) {
        return nSoundId;
      }

      nDropSound = sgptDataTable->pTxtUniqueItems[eQuality].dropsound;
    } else {
      eQuality = D2Common::ITEMS::Items::GetItemQuality(pUnit);
      if (eQuality != 5) {
        return nSoundId;
      }

      eQuality = D2Common::ITEMS::Items::ITEM_GetItemData_nFileIndex(pUnit);
      if (eQuality < 0) {
        return nSoundId;
      }
      if (eQuality >= sgptDataTable->nTxtSetItemsSize) {
        return nSoundId;
      }
      if (!(sgptDataTable->pTxtSetItems + eQuality)) {
        return nSoundId;
      }

      nDropSound = sgptDataTable->pTxtSetItems[eQuality].dropsound;
    }
    if (nDropSound <= 0) {
      return nSoundId;
    }

    nSoundId = (int32_t)nDropSound;
    return nSoundId;
}

