// Client-side packet handler that removes an item from the player's belt. Extracts item details from the raw packet bytes, looks up the player and item units, validates belt membership, clears the belt slot hover UI, removes the item's stat contributions from the player, and either drops the item to ground (if not flagged REMOVED) or removes it from the server object table. Calls ERROR_Halt on missing player/inventory.
// @sourcefile .\UNIT\Item.cpp
void __fastcall HandleItemRemoveFromBelt(uint8_t * pbParam) {
    D2UnitStrc* pBelongsResult;
    BOOL bIsBroken;
    uint32_t bIsRemoved;
    D2UnitDataItemDetailsStrc stItemDetails;
    D2InventoryStrc* pInventorySaved;
    D2InventoryStrc* pInventory;
    uint8_t* pBytesSaved = pbParam;
    D2Common::ITEMS::Items::ExtractItemDetails(pbParam + 8, pbParam[2] - 8, 0, &stItemDetails);
    D2UnitStrc* pPlayerUnit_lcl = Player::GetPlayerUnit_UI();
    if (!pPlayerUnit_lcl) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x92c);
      exit(-1);
    } else {
      D2UnitStrc* pUnit;
      pUnit = Player::UNITS_FindClientSideUnit(*(int32_t*)(pbParam + 4), UNIT_ITEM);
      pInventory = pPlayerUnit_lcl->pInventory;
      pInventorySaved = pInventory;
      if (!pInventory) {
        Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x931);
        exit(-1);
      }

      pBelongsResult = D2Common::INVENTORY::Inventory::ItemBelongsToInventoryOfPlayer(pInventory, pUnit);
      if (!pBelongsResult) {
        return;
      }
      if (pBelongsResult != pUnit) {
        Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x93a);
        exit(-1);
      }

      D2Common::INVENTORY::Inventory::INVENTORY_OnBeltChanged_NoOp(pInventory, (uint32_t)stItemDetails.x);
      UI::Panel::PANEL_ClearBeltSlotHover();
      UI::Panel::PANEL_SetBeltSlotHoverFlag((uint32_t)stItemDetails.x, 0);
      if (pPlayerUnit_lcl->eUnitType == UNIT_PLAYER) {
        D2Common::INVENTORY::Inventory::GetEquipedWeapon(pPlayerUnit_lcl->pInventory);
      }

      bIsBroken = D2Common::ITEMS::Items::CheckItemFlag(pUnit, ITEMFLAG_BROKEN, 0x96, ".\\UNIT\\Item.cpp");
      if (!bIsBroken) {
        D2Common::Stats::StatsEx::STATLIST_RemoveFromOwnerAndRecalc(pPlayerUnit_lcl, pUnit);
      }

      bIsRemoved = D2Common::ITEMS::Items::ITEMFLAG_CheckFlag(stItemDetails.flags, ITEMFLAG_REMOVED);
      if (!bIsRemoved) {
        ITEM_DropItemToGroundWithMode((uint32_t)stItemDetails.nAnimMode, 0, stItemDetails.nInvPage, 0, pUnit, 0);
        pInventory = pInventorySaved;
        D2Common::INVENTORY::Inventory::CopyInventoryOfPlayerOrFree(pInventorySaved, pUnit);
        pPlayerUnit_lcl = D2Common::INVENTORY::Inventory::INVENTORY_GetHandItem(pInventory);
        UI::ui::ITEM_SetItemOnHand(pPlayerUnit_lcl);
        ITEM_RemoveUninterruptableState(pUnit);
        return;
      }

      CUnit::RemoveObjectFromServerObjectTable(*(uint32_t*)(pBytesSaved + 4), UNIT_ITEM);
      UI::ui::ITEM_SetItemOnHand(nullptr);
      return;
    }
}

// Client handler for the incoming belt-swap packet's new item (the item being placed into the belt slot). Locates the item by GUID, sets its anim mode/page/position from packet details, re-applies charm stats if it is a charm, places it in the player inventory, and verifies it can fit in the target belt slot. Clears the cursor and removes the uninterruptable state. Halts if player/inventory is null or belt placement fails.
static void __stdcall ITEM_HandleSwapBeltNewItem(int32_t pPacket, D2UnitDataItemDetailsStrc * pItemDetails) {
    D2UnitStrc* pUnit = Player::GetPlayerUnit_UI();
    if (!pUnit) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x957);
      exit(-1);
    }

    D2UnitStrc* pItem = Player::UNITS_FindClientSideUnit(*(int32_t*)(pPacket + 4), UNIT_ITEM);
    if (!pItem) {
      return;
    }

    eInventoryPage ePage = pItemDetails->nInvPage;
    ITEM_SetAnimModeAndPlace(pItem, nullptr, 0, 0, (uint32_t)pItemDetails->nAnimMode, 0);
    D2Common::ITEMS::Items::ITEM_SetItemData_ePage(pItem, ePage);
    D2InventoryStrc* pInventory = pUnit->pInventory;
    if (!pInventory) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x963);
      exit(-1);
    }

    D2Common::Units::SetXForStaticUnit(pItem, (uint32_t)pItemDetails->x);
    D2Common::Units::SetYForStaticUnit(pItem, (uint32_t)pItemDetails->y);
    uint32_t bIsCharm = D2Common::ITEMS::Items::ITEMS_IsA(pItem, ITEMTYPE_Charm);
    if (bIsCharm) {
      ITEM_ApplySocketableAndEquipStats(0, pUnit, pItem);
    }

    BOOL bPlacedInInv = D2Common::INVENTORY::Inventory::PutItemInInventory(pInventory, pItem, 2);
    if (bPlacedInInv) {
      bIsCharm = Units::GetXPosFromDynamicPathUnit(pItem);
      bPlacedInInv = D2Common::INVENTORY::Inventory::INVENTORY_CanPlaceItemInBelt(pInventory, pItem, bIsCharm);
      if (!bPlacedInInv) {
        Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x970);
        exit(-1);
      }
    }

    UI::ui::UI_SendMouseMoveMessage();
    ITEM_RemoveUninterruptableState(pItem);
}

// Client handler for the outgoing item in a belt swap. Locates the old belt item by GUID, verifies it belongs to the player's inventory, removes its stat contributions via STATLIST_RemoveFromOwnerAndRecalc (unless broken), drops it to the ground via ITEM_DropItemToGroundWithMode, then sets the swapped-in item as the cursor item via CopyInventoryOfPlayerOrFree + ITEM_SetItemOnHand. Halts on inventory/ownership assertion failures.
// @sourcefile .\UNIT\Item.cpp
void __stdcall ITEM_HandleSwapBeltOldItem(uint8_t * pBytes, D2UnitDataItemDetailsStrc * itemDetails) {
    BOOL bIsBroken;
    D2UnitStrc* pPlayer = Player::GetPlayerUnit_UI();
    if (!pPlayer) {
      return;
    }

    D2UnitStrc* pUnit = Player::UNITS_FindClientSideUnit(*(int32_t*)(pBytes + 4), UNIT_ITEM);
    if (!pUnit) {
      return;
    }

    D2InventoryStrc* pInventory = pPlayer->pInventory;
    if (!pInventory) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x98d);
      exit(-1);
    } else {
      D2UnitStrc* pOwnerCheck;
      pOwnerCheck = D2Common::INVENTORY::Inventory::ItemBelongsToInventoryOfPlayer(pInventory, pUnit);
      if (!pOwnerCheck) {
        Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x98f);
        exit(-1);
      } else {
        if (pOwnerCheck != pUnit) {
          Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x990);
          exit(-1);
        }
        if (pPlayer->eUnitType == UNIT_PLAYER) {
          D2Common::INVENTORY::Inventory::GetEquipedWeapon(pPlayer->pInventory);
        }

        bIsBroken = D2Common::ITEMS::Items::CheckItemFlag(pUnit, ITEMFLAG_BROKEN, 0x96, ".\\UNIT\\Item.cpp");
        if (!bIsBroken) {
          D2Common::Stats::StatsEx::STATLIST_RemoveFromOwnerAndRecalc(pPlayer, pUnit);
        }

        D2Common::INVENTORY::Inventory::INVENTORY_OnBeltChanged_NoOp(pInventory, (uint32_t)itemDetails->x);
        ITEM_DropItemToGroundWithMode((uint32_t)itemDetails->nAnimMode, 0, itemDetails->nInvPage, 0, pUnit, 0);
        D2Common::INVENTORY::Inventory::CopyInventoryOfPlayerOrFree(pInventory, pUnit);
        pPlayer = D2Common::INVENTORY::Inventory::INVENTORY_GetHandItem(pInventory);
        UI::ui::ITEM_SetItemOnHand(pPlayer);
        ITEM_RemoveUninterruptableState(pUnit);
        return;
      }
    }
}

void __fastcall HandleItemSwapInBelt(uint8_t * pBytes) {
    D2UnitDataItemDetailsStrc stItemDetails;
    D2Common::ITEMS::Items::ExtractItemDetails(pBytes + 8, pBytes[2] - 8, 0, &stItemDetails);
    D2UnitStrc* pFoundItem = Player::UNITS_FindClientSideUnit(*(int32_t*)(pBytes + 4), UNIT_ITEM);
    if (!pFoundItem) {
      return;
    }
    if (pFoundItem->eAnimMode.ePlayerMode == Walk) {
      ITEM_HandleSwapBeltOldItem(pBytes, &stItemDetails);
      return;
    }
    if (pFoundItem->eAnimMode.ePlayerMode != eD2PlayerAnimMode_ns::GetHit) {
      return;
    }

    ITEM_HandleSwapBeltNewItem((int32_t)pBytes, &stItemDetails);
}

// Client-side handler that places or removes an item from the cursor. On removal (byte[1]==-1): clears ITEMFLAG_CURSOR, removes uninterruptable state, calls ITEM_SetItemOnHand(null). On pickup: auto-opens inventory if item type matches gaaCursorAutoOpenInventoryTypes, sets ITEMFLAG_CURSOR and calls CURSOR_SetCursorItem.
void __fastcall ITEM_HandleItemCursorAssign(D2GSPacketSrv0x3F * pPacket) {
    // Static local variables (originally global data)
    static uint32_t gaaCursorAutoOpenInventoryTypes[2] = { 0x0, 0x2 }; D2_STATIC_GUARD(gaaCursorAutoOpenInventoryTypes, "D2Client::UNIT::ITEM_HandleItemCursorAssign::gaaCursorAutoOpenInventoryTypes");
    static uint32_t gnCursorAutoOpenInventoryTypeCount = 0x2; D2_STATIC_GUARD(gnCursorAutoOpenInventoryTypeCount, "D2Client::UNIT::ITEM_HandleItemCursorAssign::gnCursorAutoOpenInventoryTypeCount");

    BOOL bInventoryOpen;
    D2UnitStrc* pItem;
    uint32_t nTypeIdx;
    if (pPacket->nSkillId != 0xffff) {
      nTypeIdx = 0;
      if (gnCursorAutoOpenInventoryTypeCount > 0) {
        do {
          if ((uint32_t)pPacket->nItemSlot == gaaCursorAutoOpenInventoryTypes[nTypeIdx]) {
            bInventoryOpen = UI::ui::UI_GetFlag(UI_INVENTORY);
            if (!bInventoryOpen) {
              UI::ui::SetUIFlag(UI_INVENTORY, UI_SET, 0);
              break;
            }
          }

          nTypeIdx++;
        } while (nTypeIdx < gnCursorAutoOpenInventoryTypeCount);
      }

      pItem = Player::UNITS_FindClientSideUnit(pPacket->nUnitGUID, UNIT_ITEM);
      if (pItem) {
        UI::ui::CURSOR_SetCursorItem(pItem, (uint32_t)pPacket->nItemSlot);
        return;
      }
    } else {
      if (pPacket->nItemSlot == 0xff) {
        pItem = Player::UNITS_FindClientSideUnit(pPacket->nUnitGUID, UNIT_ITEM);
        if (pItem) {
          D2Common::ITEMS::Items::ITEM_EditItemData_eItemFlag(pItem, ITEMFLAG_CURSOR, 0);
          ITEM_RemoveUninterruptableState(pItem);
        }

        UI::ui::ITEM_SetItemOnHand(nullptr);
        return;
      }

      nTypeIdx = 0;
      if (gnCursorAutoOpenInventoryTypeCount > 0) {
        do {
          if ((uint32_t)pPacket->nItemSlot == gaaCursorAutoOpenInventoryTypes[nTypeIdx]) {
            bInventoryOpen = UI::ui::UI_GetFlag(UI_INVENTORY);
            if (!bInventoryOpen) {
              UI::ui::SetUIFlag(UI_INVENTORY, UI_SET, 0);
            }
          }

          nTypeIdx++;
        } while (nTypeIdx < gnCursorAutoOpenInventoryTypeCount);
      }

      pItem = Player::UNITS_FindClientSideUnit(pPacket->nUnitGUID, UNIT_ITEM);
      if (pItem) {
        D2Common::ITEMS::Items::ITEM_EditItemData_eItemFlag(pItem, ITEMFLAG_CURSOR, 1);
        UI::ui::CURSOR_SetCursorItem(pItem, (uint32_t)pPacket->nItemSlot);
        return;
      }
    }
}

