void __fastcall ITEM_HandleServerItemAction(int32_t nParam) {
    D2UnitStrc* pUnit = Player::UNITS_FindClientSideUnit(*(int32_t*)(nParam + 2), (eD2UnitType)*(uint8_t*)(nParam + 1));
    if (!pUnit) {
      return;
    }

    ITEM_RemoveUninterruptableState(pUnit);
}

